import re, os, subprocess, collections

# collect declarations
decls = {}  # name -> list of (file, recv)
for root, dirs, files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'): continue
        p = os.path.join(root,f)
        for i,line in enumerate(open(p, encoding='utf8', errors='replace'),1):
            m = re.match(r'func (\(([^)]*)\) )?([A-Za-z0-9_]+)\(', line)
            if m:
                decls.setdefault(m.group(3), []).append((p, m.group(2) or '', i))

# gather all go source lines in repo
callcount = collections.Counter()
files = subprocess.check_output(['git','ls-files','*.go']).decode().split()
corpus = []
for p in files:
    txt = open(p, encoding='utf8', errors='replace').read()
    corpus.append((p, txt))

for name in decls:
    pat = re.compile(r'(?<![\w.])(?:[\w\)\]]+\.)?'+re.escape(name)+r'\s*\(')
    total = 0
    for p, txt in corpus:
        for line in txt.split('\n'):
            if re.match(r'\s*func ', line) and re.search(r'func (\([^)]*\) )?'+re.escape(name)+r'\(', line):
                continue
            total += len(pat.findall(line))
    callcount[name] = total

for name, c in callcount.most_common(35):
    print(c, name, decls[name][:3])
EOF

