package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type key struct {
	name string
	pos  token.Position
}

func main() {
	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:   "/bench/repo",
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	counts := map[types.Object]int{}
	countsProd := map[types.Object]int{}
	callerFiles := map[types.Object]map[string]bool{}
	seen := map[*packages.Package]bool{}
	var visit func(p *packages.Package)
	visit = func(p *packages.Package) {
		if seen[p] {
			return
		}
		seen[p] = true
		if !strings.HasPrefix(p.PkgPath, "github.com/usememos/memos") {
			return
		}
		for _, f := range p.Syntax {
			fname := p.Fset.Position(f.Pos()).Filename
			isTest := strings.HasSuffix(fname, "_test.go")
			ast.Inspect(f, func(n ast.Node) bool {
				ce, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				var id *ast.Ident
				switch fn := ast.Unparen(ce.Fun).(type) {
				case *ast.Ident:
					id = fn
				case *ast.SelectorExpr:
					id = fn.Sel
				default:
					return true
				}
				obj := p.TypesInfo.Uses[id]
				if obj == nil {
					obj = p.TypesInfo.Defs[id]
				}
				if obj == nil {
					return true
				}
				fnObj, ok := obj.(*types.Func)
				if !ok {
					return true
				}
				pos := p.Fset.Position(fnObj.Pos())
				if !strings.Contains(pos.Filename, "/bench/repo/internal/") {
					return true
				}
				counts[fnObj]++
				if !isTest {
					countsProd[fnObj]++
				}
				if callerFiles[fnObj] == nil {
					callerFiles[fnObj] = map[string]bool{}
				}
				callerFiles[fnObj][strings.TrimPrefix(fname, "/bench/repo/")] = true
				return true
			})
		}
	}
	for _, p := range pkgs {
		packages.Visit([]*packages.Package{p}, func(pp *packages.Package) bool { visit(pp); return true }, nil)
	}
	// dedupe objects by position (Tests:true duplicates packages)
	type agg struct {
		obj   types.Object
		all   int
		prod  int
		files map[string]bool
	}
	byPos := map[string]*agg{}
	for o, c := range counts {
		pos := o.Pkg().Path() + "." + o.(*types.Func).FullName()
		a := byPos[pos]
		if a == nil {
			a = &agg{obj: o, files: map[string]bool{}}
			byPos[pos] = a
		}
		if c > a.all {
			a.all = c
			a.prod = countsProd[o]
			a.files = callerFiles[o]
		}
	}
	list := []*agg{}
	for _, a := range byPos {
		list = append(list, a)
	}
	sort.Slice(list, func(i, j int) bool { return list[i].all > list[j].all })
	fset := token.NewFileSet()
	_ = fset
	for i, a := range list {
		if i >= 25 {
			break
		}
		fmt.Printf("%-4d prod=%-4d %s\n", a.all, a.prod, a.obj.(*types.Func).FullName())
	}
	fmt.Fprintln(os.Stderr, "done")
	// print caller file breakdown for top 8
	fmt.Println("\n--- caller files for top 8 ---")
	for i, a := range list {
		if i >= 8 {
			break
		}
		fs := []string{}
		for f := range a.files {
			fs = append(fs, f)
		}
		sort.Strings(fs)
		fmt.Printf("%s (%d): %v\n", a.obj.(*types.Func).FullName(), a.all, fs)
	}
}
EOF
